#include "cloudmoon_upgrade.h"
#include <stdio.h>
#include <string.h>
#include <ctype.h>
typedef struct{uint32_t h[5];uint64_t bits;uint8_t block[64];size_t used;} sha1_ctx;
static uint32_t rol(uint32_t x,unsigned n){return(x<<n)|(x>>(32U-n));}
static void sha1_block(sha1_ctx*c,const uint8_t*p){uint32_t w[80],a,b,d,e,f,k,t,cc;unsigned i;for(i=0;i<16;i++)w[i]=((uint32_t)p[i*4]<<24)|((uint32_t)p[i*4+1]<<16)|((uint32_t)p[i*4+2]<<8)|p[i*4+3];for(i=16;i<80;i++)w[i]=rol(w[i-3]^w[i-8]^w[i-14]^w[i-16],1);a=c->h[0];b=c->h[1];cc=c->h[2];d=c->h[3];e=c->h[4];for(i=0;i<80;i++){if(i<20){f=(b&cc)|((~b)&d);k=0x5a827999U;}else if(i<40){f=b^cc^d;k=0x6ed9eba1U;}else if(i<60){f=(b&cc)|(b&d)|(cc&d);k=0x8f1bbcdcU;}else{f=b^cc^d;k=0xca62c1d6U;}t=rol(a,5)+f+e+k+w[i];e=d;d=cc;cc=rol(b,30);b=a;a=t;}c->h[0]+=a;c->h[1]+=b;c->h[2]+=cc;c->h[3]+=d;c->h[4]+=e;}
static void sha1_init(sha1_ctx*c){memset(c,0,sizeof(*c));c->h[0]=0x67452301U;c->h[1]=0xefcdab89U;c->h[2]=0x98badcfeU;c->h[3]=0x10325476U;c->h[4]=0xc3d2e1f0U;}
static void sha1_update(sha1_ctx*c,const uint8_t*p,size_t n){c->bits+=(uint64_t)n*8U;while(n){size_t z=64-c->used;if(z>n)z=n;memcpy(c->block+c->used,p,z);c->used+=z;p+=z;n-=z;if(c->used==64){sha1_block(c,c->block);c->used=0;}}}
static void sha1_final(sha1_ctx*c,uint8_t out[20]){uint64_t bits=c->bits;unsigned i;c->block[c->used++]=128;if(c->used>56){while(c->used<64)c->block[c->used++]=0;sha1_block(c,c->block);c->used=0;}while(c->used<56)c->block[c->used++]=0;for(i=0;i<8;i++)c->block[63-i]=(uint8_t)(bits>>(i*8));sha1_block(c,c->block);for(i=0;i<5;i++){out[i*4]=(uint8_t)(c->h[i]>>24);out[i*4+1]=(uint8_t)(c->h[i]>>16);out[i*4+2]=(uint8_t)(c->h[i]>>8);out[i*4+3]=(uint8_t)c->h[i];}}
static const char b64[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static void base64(const uint8_t*in,size_t n,char*out){size_t i=0,o=0;while(i<n){uint32_t v=(uint32_t)in[i++]<<16;int h2=0,h3=0;if(i<n){v|=(uint32_t)in[i++]<<8;h2=1;}if(i<n){v|=in[i++];h3=1;}out[o++]=b64[(v>>18)&63];out[o++]=b64[(v>>12)&63];out[o++]=h2?b64[(v>>6)&63]:'=';out[o++]=h3?b64[v&63]:'=';}out[o]=0;}
int cm_ws_generate_client_key(cm_random_source_fn source,void*ctx,char key[25]){uint8_t nonce[16];if(!key||cm_random_bytes(source,ctx,nonce,sizeof(nonce)))return -1;base64(nonce,sizeof(nonce),key);return 0;}
static int safe_header_value(const char*s){if(!s||!*s)return 0;for(;*s;s++)if(*s=='\r'||*s=='\n'||*s==' '||*s=='\t')return 0;return 1;}
int cm_ws_build_upgrade_request(char*out,size_t cap,const char*host,const char*path,const uint8_t nonce[16],char key[25]){int n;if(!out||!host||!path||!nonce||!key||!safe_header_value(host)||path[0]!='/'||strchr(path,'\r')||strchr(path,'\n'))return -1;{const unsigned char*q=(const unsigned char*)path;for(;*q;q++)if(*q<=32||*q==127)return -1;}base64(nonce,16,key);n=snprintf(out,cap,"GET %s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n\r\n",path,host,key);if(n<0||(size_t)n>=cap){out[0]=0;key[0]=0;return -1;}return n;}
static int eq_ci(const char*a,size_t n,const char*b){size_t i;if(strlen(b)!=n)return 0;for(i=0;i<n;i++)if(tolower((unsigned char)a[i])!=tolower((unsigned char)b[i]))return 0;return 1;}
static int token_contains(const char*v,size_t n,const char*t){size_t i=0,tn=strlen(t);while(i<n){size_t s,e;while(i<n&&(v[i]==' '||v[i]=='\t'||v[i]==','))i++;s=i;while(i<n&&v[i]!=',')i++;e=i;while(e>s&&(v[e-1]==' '||v[e-1]=='\t'))e--;if(e-s==tn&&eq_ci(v+s,e-s,t))return 1;}return 0;}
int cm_ws_validate_upgrade_response(const char*r,size_t len,const char key[25]){static const char guid[]="258EAFA5-E914-47DA-95CA-C5AB0DC85B11";char expected[29],joined[24+sizeof(guid)-1];uint8_t digest[20];sha1_ctx c;size_t pos=0,end;int status=0,upgrade=0,connection=0,accept=0;if(!r||!key||len<4||len>16384)return -1;{size_t i;for(i=0;i+3<len;i++)if(!memcmp(r+i,"\r\n\r\n",4))break;if(i+3>=len)return -1;}memcpy(joined,key,24);memcpy(joined+24,guid,sizeof(guid)-1);sha1_init(&c);sha1_update(&c,(const uint8_t*)joined,sizeof(joined));sha1_final(&c,digest);base64(digest,20,expected);while(pos<len){size_t colon,vs,ve;end=pos;while(end+1<len&&!(r[end]=='\r'&&r[end+1]=='\n'))end++;if(end+1>=len)return -1;if(end==pos)break;if(pos==0){if(end<12||memcmp(r,"HTTP/1.1 101",12))return -1;status=1;}else{colon=pos;while(colon<end&&r[colon]!=':')colon++;if(colon==end)return -1;vs=colon+1;while(vs<end&&(r[vs]==' '||r[vs]=='\t'))vs++;ve=end;while(ve>vs&&(r[ve-1]==' '||r[ve-1]=='\t'))ve--;if(eq_ci(r+pos,colon-pos,"Upgrade")){if(!eq_ci(r+vs,ve-vs,"websocket"))return -1;upgrade=1;}else if(eq_ci(r+pos,colon-pos,"Connection")){if(!token_contains(r+vs,ve-vs,"Upgrade"))return -1;connection=1;}else if(eq_ci(r+pos,colon-pos,"Sec-WebSocket-Accept")){if(ve-vs!=28||memcmp(r+vs,expected,28))return -1;accept=1;}}pos=end+2;}return status&&upgrade&&connection&&accept?0:-1;}
